function questionRegion(q){const r=(q.answer_region_details||[])[0],l=r?.location||{},s=r?.structure||{};if(!r)return '未定位填写区域';if(l.type==='docx')return `填写区域：表格 ${l.table??'—'} · 第 ${s.row_start??l.row??'—'} 行 · 网格列 ${s.grid_col_start??s.column_start??'—'} · ${({blank:'原填写位为空',filled:'原填写位已有值',unresolved:'原填写位需要核对',unreadable:'原填写位无法读取',not_located:'填写位尚未确定'}[q.form_definition?.existing_value_status])||'原填写状态待核对'}`;if(l.type==='pdf')return `填写区域：PDF 第 ${l.page??'—'} 页（标准 Word 导出）`;return '填写区域已定位'}
const responsibilityName=x=>({our_side:'我方填写',customer:'客户填写',reviewer:'审核人员填写',shared:'共同填写',unknown:'责任不明确'}[x]||'责任不明确');
const fieldTypeName=x=>({short_text:'短文本',long_text:'长文本',integer:'整数',decimal:'小数',date:'日期',single_select:'单选',multi_select:'多选',address:'地址',contact:'联系方式',attachment_reference:'附件引用',repeating_record:'重复记录',composite:'复合字段',manual_signature:'人工签署'}[x]||x||'未判断');
