 let tables=d.tables.map(t=>{const maxCol=Math.max(1,...t.rows.flatMap(row=>row.cells.map(c=>c.structure.grid_col_end||c.structure.grid_col_start||1)));return `<section><h3>表格 ${t.table??'—'}</h3><div class="native-table">${t.rows.map(row=>`<div class="native-row" style="grid-template-columns:repeat(${maxCol},minmax(34px,1fr))">${row.cells.map(c=>{const fill=c.fill_for.length,labels=c.label_for.length,status=c.region_status||'',kind=status==='mapped_fill'?(c.structure.blank_state==='blank'?'fill-blank':'fill-existing'):status==='fixed_label'?'fixed-label':status==='unmapped_blank'?'unmapped-blank':status==='merge_continuation'?'merge-cell':status==='unmapped_control'?'unmapped-control':'fixed-content',mark=status==='mapped_fill'?'F':status==='fixed_label'?'L':status==='unmapped_blank'?'R':status==='merge_continuation'?'M':status==='unmapped_control'?'C':'·',selectedTarget=selected&&c.fill_for.includes(selected)?'selected-target':'';return `<button class="native-cell ${kind} ${selectedTarget}" style="grid-column:${c.structure.grid_col_start}/${(c.structure.grid_col_end||c.structure.grid_col_start)+1}" data-region-block="${c.block_id}" data-region-field="${fill?c.fill_for[0]:labels?c.label_for[0]:''}"><b>${mark}</b><span>${esc(c.text||'（空白）')}</span><small>行 ${c.structure.row_start} · 列 ${c.structure.grid_col_start}-${c.structure.grid_col_end}</small></button>`}).join('')}</div>`).join('')}</div></section>`}).join('');
 tables+=nativeExtraPreview(d,selected);
 $('#modalBody').insertAdjacentHTML('beforeend',`<section class="fill-preview"><header><div><h2>Word 填写位置清单</h2><p>F 已定位填写区；L 固定标签；R 未配对空白格；M 合并延续格；C 控件；· 固定内容。</p><p>物理单元格 ${summary.physical_cells??0}；已定位字段 ${summary.located_fields??0}；未定位字段 ${summary.unlocated_fields??0}；未配对空白格 ${summary.unmapped_blank_cells??0}。</p></div><button data-close-fill-preview>返回填写页</button></header><div class="mapping-toolbar"><label>当前要定位的字段<select data-mapping-field><option value="">仅查看，不修改</option>${d.fields.map(f=>`<option value="${f.id}">${esc(f.question_text.slice(0,80))}</option>`).join('')}</select></label><span>${selected?'已高亮该字段现有填写位置；点击其他未配对空白格可以改正。':'选择字段后可以核对它在 Word 表格中的填写位置。'}</span></div><div class="fill-preview-body"><main>${tables||'<p>当前文件没有可展示的 Word 表格结构。</p>'}</main><aside id="fillRegionDetail"><p>点击单元格查看物理位置和关联字段。</p></aside></div></section>`);
 const picker=$('[data-mapping-field]');picker.value=selected;picker.onchange=()=>{$('.fill-preview').remove();openFillRegionPreview(id,picker.value)};
 $('.fill-preview h2').textContent=(d.pages||[]).length?'PDF 原页与填写位置':'Word 填写位置清单';
 if((d.pages||[]).length)$('.mapping-toolbar>span').textContent='点击原 PDF 中的 F 填写区或 L 标签，核对字段及来源位置。';
 $('[data-close-fill-preview]').onclick=()=>$('.fill-preview').remove();
 $$('[data-region-block]').forEach(x=>x.onclick=()=>{const cell=cellMap.get(x.dataset.regionBlock),field=fieldMap.get(x.dataset.regionField);if(field)showFillRegionDetail(id,field,cell);else showCellMappingDetail(id,selected,fieldMap,cell)});
 if(selected){const target=$('.native-cell.selected-target');target?.scrollIntoView({block:'center',behavior:'smooth'});showFillRegionDetail(id,fieldMap.get(selected));}
